SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "明宣宗在南郊祭祀天地", "description": "宣德二年正月庚子，明宣宗朱瞻基在南郊举行祭祀天地的大典。", "start_year": 1427, "end_year": 1427, "time_original": "宣德二年正月庚子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "19527786-d0e3-52c8-a697-87ac90ecf240"}, {"title": "明宣宗听取囚犯数目报告后命加强教化", "description": "宣德二年正月丁未，主管官署报告全年审讯囚犯的数目。明宣宗朱瞻基认为民众轻易犯法与教化未及有关，命官员重申教化。", "start_year": 1427, "end_year": 1427, "time_original": "宣德二年正月丁未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "13ea206f-ce35-5ea3-89a1-6f6a26de69c3"}, {"title": "陈山升任户部尚书，兼谨身殿大学士", "description": "宣德2年（1427年）二月，陈山升任户部尚书，兼谨身殿大学士。", "start_year": 1427, "end_year": 1427, "time_original": "宣德2年（1427年）二月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "6e53bfe8-e283-5691-bffa-411c734e83b5"}, {"title": "黎利攻打交阯城，被王通击退", "description": "宣德二年二月乙丑，黎利所部攻打交阯城，王通领军将其击退。", "start_year": 1427, "end_year": 1427, "time_original": "宣德二年二月乙丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "307f0126-e690-5bd0-ae13-4f06d24dd5e0"}, {"title": "明廷授予马愉等人不同等第的进士资格", "description": "宣德二年三月辛卯，朝廷授予马愉等人不同等第的进士资格。", "start_year": 1427, "end_year": 1427, "time_original": "宣德二年三月辛卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "77df69af-d5d6-5eb3-ae17-b69756871dba"}, {"title": "黎利攻陷昌江，李任等人在战事中身亡", "description": "宣德二年四月庚申，黎利所部攻陷昌江。都指挥李任、指挥顾福和刘顺、知府刘子辅及宦官冯智在战事中身亡。", "start_year": 1427, "end_year": 1427, "time_original": "宣德二年四月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c4df51db-7d9a-57cc-9fea-596098f19b4e"}, {"title": "晋王朱济熿获罪被废为庶人", "description": "宣德二年四月甲子，晋王朱济熿获罪，明廷废去其王爵，将他降为庶人。", "start_year": 1427, "end_year": 1427, "time_original": "宣德二年四月甲子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9861e728-a204-5999-b8d6-6b23482bf7be"}, {"title": "王通答应与黎利议和", "description": "宣德二年四月己巳，明将王通答应与黎利议和。", "start_year": 1427, "end_year": 1427, "time_original": "宣德二年四月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2866f230-3ace-561b-9db8-ebe77865b96d"}, {"title": "薛禄在开平督办军饷", "description": "宣德二年五月癸巳，薛禄在开平督办军饷。", "start_year": 1427, "end_year": 1427, "time_original": "宣德二年五月癸巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7402d624-5a4c-5849-9a4d-3ec2960ee2e2"}, {"title": "明仁宗神主入祀太庙", "description": "宣德二年五月己亥，朝廷将明仁宗朱高炽的神主入祀太庙。", "start_year": 1427, "end_year": 1427, "time_original": "宣德二年五月己亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6ea6f3ba-8123-5a98-b4eb-0812454cda83"}, {"title": "明廷审录在押囚犯", "description": "宣德二年五月丙午，朝廷审录在押囚犯。", "start_year": 1427, "end_year": 1427, "time_original": "宣德二年五月丙午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "70eef52b-d6e4-51cd-a4bf-3509f7911106"}, {"title": "明廷再次审录在押囚犯", "description": "宣德二年六月戊寅，朝廷审录在押囚犯。", "start_year": 1427, "end_year": 1427, "time_original": "宣德二年六月戊寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6488ed45-ee5f-543f-a073-4eace303e67d"}, {"title": "黎利攻陷隘留关，明廷逮捕顾兴祖查办", "description": "宣德二年七月己亥，黎利攻陷隘留关。朝廷以镇远侯顾兴祖领兵而未救援为由，将他逮捕查办。", "start_year": 1427, "end_year": 1427, "time_original": "宣德二年七月己亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e94d6e44-dc2b-5475-a2d4-9a86d0578661"}, {"title": "明廷审录在押囚犯", "description": "宣德二年七月庚子，朝廷审录在押囚犯。", "start_year": 1427, "end_year": 1427, "time_original": "宣德二年七月庚子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cb00ac3a-cd00-55e7-add8-f1b34947a461"}, {"title": "陈怀受任总兵官，奉命赴松潘出兵", "description": "宣德二年七月辛丑，明廷任命都督同知陈怀为总兵官，命他领兵征讨松潘一带反抗朝廷的当地居民。", "start_year": 1427, "end_year": 1427, "time_original": "宣德二年七月辛丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7790cd64-8f50-5878-a5f5-740249cb5793"}, {"title": "薛禄在开平击败对手", "description": "宣德二年七月丁未，薛禄所部在开平交战并获胜。", "start_year": 1427, "end_year": 1427, "time_original": "宣德二年七月丁未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4b3e817c-3ad3-59d8-87eb-8a47f6cec080"}, {"title": "黄淮退休", "description": "宣德2年（1427年）八月，黄淮退休。", "start_year": 1427, "end_year": 1427, "time_original": "宣德2年（1427年）八月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "ea2f5fda-6ead-514d-ac59-beea73eab2a2"}, {"title": "明廷豁免两京和晋豫部分灾区税粮", "description": "宣德二年八月，朝廷免除两京、山西、河南受灾州县的税粮。", "start_year": 1427, "end_year": 1427, "time_original": "宣德二年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5f853baf-e831-5895-ae4a-e83de3bc2bd7"}, {"title": "明廷审录在押囚犯", "description": "宣德二年九月壬辰，朝廷审录在押囚犯。", "start_year": 1427, "end_year": 1427, "time_original": "宣德二年九月壬辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6626c393-fbf3-5116-8020-c8608b99e9b3"}, {"title": "柳升所部在倒马坡遇伏，柳升阵亡", "description": "宣德二年九月乙未，柳升率领的军队到达倒马坡时遭遇伏击，柳升在战斗中身亡。", "start_year": 1427, "end_year": 1427, "time_original": "宣德二年九月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ef60f6d9-90fa-53de-a8bd-eb96564aafc4"}, {"title": "保定伯梁铭在战事期间病逝", "description": "宣德二年九月乙未，军队遇伏当天，保定伯梁铭因病去世。", "start_year": 1427, "end_year": 1427, "time_original": "宣德二年九月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "237ed76e-a6c0-5d28-8658-32f89cb93219"}, {"title": "尚书李庆在军中病逝", "description": "宣德二年九月丙申，尚书李庆在交阯战事期间因病去世。", "start_year": 1427, "end_year": 1427, "time_original": "宣德二年九月丙申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "278b34a8-93c2-5f60-acde-4975d18c4f16"}, {"title": "明军在交阯溃败，崔聚等人身亡", "description": "宣德二年九月，明军在交阯战事中溃败。参将崔聚、郎中史安、主事陈镛和李宗昉在败军中身亡。", "start_year": 1427, "end_year": 1427, "time_original": "宣德二年九月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e8ed8d05-ae5a-5645-93bf-fec6c79cd039"}, {"title": "王通放弃交阯，与黎利会盟", "description": "宣德二年十月戊寅，明军将领王通放弃交阯，与黎利会盟。", "start_year": 1427, "end_year": 1427, "time_original": "宣德二年十月戊寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "32e47f9e-81ca-56a0-88ac-5f02c45787af"}, {"title": "明廷赦免黎利，派使者赴安南并召回明朝文武人员", "description": "宣德二年十一月乙酉，明廷赦免黎利，遣侍郎李琦、罗汝敬赴安南办理册立陈暠为国王的事项，并召回在当地的文武官员和军士。", "start_year": 1427, "end_year": 1427, "time_original": "宣德二年十一月乙酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cf5f618b-d488-5079-9db3-998e311fa8fd"}, {"title": "明廷因皇长子出生颁布大赦，减免次年税粮", "description": "宣德二年十一月己亥，明廷因皇长子出生大赦天下，免除次年三分之一的税粮。", "start_year": 1427, "end_year": 1427, "time_original": "宣德二年十一月己亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fa27b275-9066-55a5-9e37-0e7ff5e10b5b"}, {"title": "明廷救济陕西饥民并发放十五万匹绢布", "description": "宣德二年十二月丁丑，朝廷赈济陕西的饥民，另发放绢布十五万匹。", "start_year": 1428, "end_year": 1428, "time_original": "宣德二年十二月丁丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "444aa2e1-520e-50a6-8fff-4de439c9f5a9"}, {"title": "本纪汇记宣德二年多地入贡", "description": "宣德二年，爪哇、占城、暹罗、琉球、瓦剌、哈密、亦力把里和撒马儿罕入贡。 按原历纪年，事情发生在公元1427至1428年之间。", "start_year": null, "end_year": null, "time_original": "宣德二年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8923c426-6c2b-52b2-893e-a8b7beae59f6"}, {"title": "明宣宗在南郊祭祀天地", "description": "宣德三年正月甲午，明宣宗朱瞻基在南郊举行祭祀天地的大典。", "start_year": 1428, "end_year": 1428, "time_original": "宣德三年正月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7ae0c350-dd50-5842-a008-549487b67630"}, {"title": "陈怀平息松潘战事", "description": "宣德三年正月丙申，《明史》本纪记陈怀率军平息松潘一带的战事。", "start_year": 1428, "end_year": 1428, "time_original": "宣德三年正月丙申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "90bc4705-1244-5741-8055-e228cd75f148"}, {"title": "明宣宗册立长子朱祁镇为皇太子", "description": "宣德三年二月戊午，明宣宗朱瞻基立皇长子朱祁镇为皇太子。", "start_year": 1428, "end_year": 1428, "time_original": "宣德三年二月戊午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "33ba34cf-e2fb-5ceb-99cb-251d68088a78"}, {"title": "《帝训》编成", "description": "宣德三年二月，《明史》本纪记《帝训》写成。", "start_year": 1428, "end_year": 1428, "time_original": "宣德三年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8dfddbe1-f455-554b-b81a-5288f7469b70"}, {"title": "明宣宗废胡皇后，册立孙贵妃为皇后", "description": "宣德三年三月癸未，明宣宗朱瞻基废去胡善祥的皇后名位，改立贵妃孙氏为皇后。", "start_year": 1428, "end_year": 1428, "time_original": "宣德三年三月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3d171c24-10d0-5e80-b388-6d8a9f551861"}, {"title": "明廷审录在押囚犯", "description": "宣德三年三月壬辰，朝廷审录在押囚犯。", "start_year": 1428, "end_year": 1428, "time_original": "宣德三年三月壬辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "09b60e96-5edc-5258-953e-5a6bd6e6e07a"}, {"title": "明廷命有关官员会商官民建议并如实报告", "description": "宣德三年四月癸亥，明廷命尚书、都御史和给事中共同审议官员、百姓进呈的建议，如实上报。", "start_year": 1428, "end_year": 1428, "time_original": "宣德三年四月癸亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "aafdaa6e-fc83-535c-a057-a5697211ddbd"}, {"title": "明廷审录在押囚犯", "description": "宣德三年闰四月壬寅，朝廷审录在押囚犯。", "start_year": 1428, "end_year": 1428, "time_original": "宣德三年闰四月壬寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bb02d635-bcc9-50d1-86fe-e4151554eb67"}, {"title": "明廷豁免山西旱灾地区的税粮", "description": "宣德三年闰四月，朝廷免去山西旱灾地区应缴的税粮。", "start_year": 1428, "end_year": 1428, "time_original": "宣德三年闰四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "903e0f25-3c08-58a6-832c-5bdee506eaa2"}, {"title": "明廷命主管官署救济灾民", "description": "宣德三年闰四月甲辰，朝廷命主管官署施行赈济。", "start_year": 1428, "end_year": 1428, "time_original": "宣德三年闰四月甲辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "aabf76f9-808d-5838-99e0-a146e98667f9"}, {"title": "明廷追究放弃交阯的责任，王通等被下狱论死", "description": "宣德三年闰四月庚戌，明廷追究放弃交阯的责任。王通等人与布政使弋谦、宦官山寿和马骐被关押并论以死罪，家产被登记没收。镇远侯顾兴祖同时被下狱。", "start_year": 1428, "end_year": 1428, "time_original": "宣德三年闰四月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2e21aba8-87d6-5cda-9b3a-dd5b78bb3a22"}, {"title": "李琦等返朝，黎利上表称陈暠已死并请求暂管国事", "description": "宣德三年五月壬子，李琦和罗汝敬返朝。本纪接着记黎利上表，声称陈暠已经去世且无子孙，请求自己暂管当地、等候明廷命令。", "start_year": 1428, "end_year": 1428, "time_original": "宣德三年五月壬子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4995981d-c9ca-544d-80d0-0b70e63268e1"}, {"title": "明廷审录在押囚犯", "description": "宣德三年五月辛酉，朝廷审录在押囚犯。", "start_year": 1428, "end_year": 1428, "time_original": "宣德三年五月辛酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7fe9ea1c-bae0-5642-845c-e6c30c9a7e00"}, {"title": "明廷再遣使者，要求黎利拥立陈氏后裔", "description": "宣德三年五月己巳，朝廷再次派罗汝敬等人前往安南，晓谕黎利拥立陈氏后裔。", "start_year": 1428, "end_year": 1428, "time_original": "宣德三年五月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d451f141-0b8f-5be7-9e98-66797c6b066a"}, {"title": "明廷追赠在交阯因公身亡的官员", "description": "宣德三年五月辛未，朝廷追赠在交阯因公身亡的官员。", "start_year": 1428, "end_year": 1428, "time_original": "宣德三年五月辛未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "99f17106-1f16-5465-a503-c2aab605add6"}, {"title": "明廷减免北京灾区夏税", "description": "宣德三年五月壬申，朝廷免去北京受灾地区的夏税。", "start_year": 1428, "end_year": 1428, "time_original": "宣德三年五月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ea62fd45-9887-5c90-abf7-e382ab0ffe4d"}, {"title": "明廷免除陕西灾区夏税", "description": "宣德三年六月丙戌，朝廷免去陕西受灾地区的夏税。", "start_year": 1428, "end_year": 1428, "time_original": "宣德三年六月丙戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6e4ce7f6-49fa-51d5-9653-e841575356de"}, {"title": "刘观巡视河道", "description": "宣德3年（年号对照1428年）六月，刘观巡视河道。", "start_year": 1428, "end_year": 1428, "time_original": "宣德3年（年号对照1428年）六月；公元年核为1428年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "51d32081-acca-5cda-882e-8de0aa6ec7c9"}, {"title": "明廷审录在押囚犯", "description": "宣德三年七月戊辰，朝廷审录在押囚犯。", "start_year": 1428, "end_year": 1428, "time_original": "宣德三年七月戊辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "64a038e7-2f3c-56c2-b778-4a75d48c97b1"}, {"title": "明廷撤销北京行部与行后军都督府", "description": "宣德三年八月辛卯，朝廷撤销北京行部和行后军都督府。", "start_year": 1428, "end_year": 1428, "time_original": "宣德三年八月辛卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4ab9e2f5-f662-58e0-8532-93c2ad2dca93"}, {"title": "明宣宗亲自率军巡边", "description": "宣德三年八月丁未，明宣宗朱瞻基亲自带兵巡视边境。", "start_year": 1428, "end_year": 1428, "time_original": "宣德三年八月丁未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fde22eee-a7c7-5bba-af09-fda524104e9b"}, {"title": "明宣宗行至石门驿，率军应对进犯会州的兀良哈部", "description": "宣德三年九月辛亥，明宣宗朱瞻基行至石门驿。得知兀良哈部进犯会州，他率三千名精兵前去应战。", "start_year": 1428, "end_year": 1428, "time_original": "宣德三年九月辛亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "97603e63-f179-5408-9c0a-620b31f054d9"}, {"title": "明宣宗在宽河率军击败兀良哈部", "description": "宣德三年九月乙卯，明宣宗朱瞻基出喜峰口，在宽河与兀良哈部交战。明军取胜，来战者中有人被俘，其首领被杀。", "start_year": 1428, "end_year": 1428, "time_original": "宣德三年九月乙卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b96a46c7-9135-50b7-97a4-9f409e8d3c20"}, {"title": "明宣宗率军班师", "description": "宣德三年九月甲子，明宣宗率军返回。", "start_year": 1428, "end_year": 1428, "time_original": "宣德三年九月甲子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c2419b20-3d8e-547f-a31b-55befedd6de7"}, {"title": "明宣宗从喜峰口回京", "description": "宣德三年九月癸酉，明宣宗朱瞻基从喜峰口回到京师。", "start_year": 1428, "end_year": 1428, "time_original": "宣德三年九月癸酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "dc725458-e4ca-5d36-8240-86b0fd0e4f8f"}, {"title": "明宣宗驳回钟法保采珠请求，将其下狱", "description": "宣德三年十一月癸酉，锦衣指挥钟法保请求在东莞采珠。明宣宗朱瞻基认为此举会扰民牟利，将他下狱。", "start_year": 1429, "end_year": 1429, "time_original": "宣德三年十一月癸酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4898d723-2375-59e8-8b02-ccde317b7365"}, {"title": "山云在忻城出兵并俘获当地对手", "description": "宣德三年十二月庚子，广西总兵官山云出兵攻打忻城一带反抗明廷的居民，并抓获其中一些人。", "start_year": 1429, "end_year": 1429, "time_original": "宣德三年十二月庚子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9973de74-9ff9-5cd7-959d-9cc2545c625d"}, {"title": "本纪汇记宣德三年多地入贡", "description": "宣德三年，占城、暹罗、爪哇、琉球、瓦剌、哈密、安南、曲先、土鲁番、亦力把里和撒马儿罕入贡。 按原历纪年，事情发生在公元1428至1429年之间。", "start_year": null, "end_year": null, "time_original": "宣德三年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2dcad285-492b-54ff-a244-2f2856591e96"}]'::jsonb)
